import{_ as o,o as t,c as r,a2 as e}from"./chunks/framework.DHtetOlu.js";const u=JSON.parse('{"title":"Arquivos, importar e exportar","description":"","frontmatter":{},"headers":[],"relativePath":"guide/files.md","filePath":"guide/files.md"}'),s={name:"guide/files.md"};function i(d,a,n,c,m,l){return t(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="arquivos-importar-e-exportar" tabindex="-1">Arquivos, importar e exportar <a class="header-anchor" href="#arquivos-importar-e-exportar" aria-label="Permalink to &quot;Arquivos, importar e exportar&quot;">​</a></h1><h2 id="projetos" tabindex="-1">Projetos <a class="header-anchor" href="#projetos" aria-label="Permalink to &quot;Projetos&quot;">​</a></h2><p>O projeto é um arquivo <strong><code>.magfem</code></strong> (JSON) com o desenho, as variáveis, os materiais, a malha, as físicas e as vistas. Os resultados são recalculados ao abrir.</p><ul><li><strong>Novo</strong>, <strong>Abrir</strong>, <strong>Salvar</strong> e <strong>Salvar como</strong> ficam na barra superior.</li><li>No Chrome e no Edge, <strong>Salvar</strong> regrava o mesmo arquivo, como num programa instalado; <strong>Salvar como</strong> escolhe outro. No Firefox e no Safari, salvar faz um download.</li><li>Nada sai da sua máquina: não há servidor, conta nem nuvem.</li></ul><h2 id="rascunho-e-copias-automaticas" tabindex="-1">Rascunho e cópias automáticas <a class="header-anchor" href="#rascunho-e-copias-automaticas" aria-label="Permalink to &quot;Rascunho e cópias automáticas&quot;">​</a></h2><p>O projeto aberto é guardado no navegador (rascunho) a cada mudança: fechar a aba sem salvar não perde o trabalho. Além disso, a cada minuto de edição a versão anterior vira uma <strong>cópia automática</strong> (até 10). Se o projeto abrir vazio, uma faixa oferece recuperar a última cópia; a lista completa fica em <strong>Cópias automáticas</strong>. Recuperar pode ser desfeito.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>O rascunho vive no armazenamento do navegador. Limpar os dados do site apaga o rascunho e as cópias. Salve os projetos importantes em arquivo.</p></div><h2 id="importar" tabindex="-1">Importar <a class="header-anchor" href="#importar" aria-label="Permalink to &quot;Importar&quot;">​</a></h2><p><strong>Importar</strong> aceita:</p><table tabindex="0"><thead><tr><th>Formato</th><th>O que entra</th></tr></thead><tbody><tr><td>DXF</td><td>linhas, arcos, círculos e polilinhas; pontos coincidentes são unidos para as regiões fecharem</td></tr><tr><td>SVG</td><td>caminhos (com arcos) convertidos em linhas e arcos</td></tr><tr><td>FEMM (<code>.fem</code>)</td><td>geometria, materiais, contornos, circuitos e <em>block labels</em>. Regiões sem rótulo ficam fora da malha, e bordas sem propriedade ficam Neumann, como no FEMM</td></tr></tbody></table><p>Materiais do FEMM também estão em <strong>Materiais › Importar do FEMM…</strong> (lê o <code>matlib.dat</code>) e na busca da lista de materiais.</p><h2 id="exportar" tabindex="-1">Exportar <a class="header-anchor" href="#exportar" aria-label="Permalink to &quot;Exportar&quot;">​</a></h2><p>O botão <strong>Exportar</strong> (barra superior) exporta o que está na aba ativa:</p><table tabindex="0"><thead><tr><th>Aba ativa</th><th>Formatos</th></tr></thead><tbody><tr><td>Desenho</td><td>SVG (vetorial, em mm), DXF (LibreCAD, FreeCAD…), PNG, JPG</td></tr><tr><td>Vista de campo</td><td>PNG, JPG</td></tr><tr><td>Gráfico</td><td>SVG, PNG, JPG, CSV</td></tr><tr><td>Tabela</td><td>CSV</td></tr></tbody></table><p>Além disso:</p><table tabindex="0"><thead><tr><th>O quê</th><th>Onde</th></tr></thead><tbody><tr><td>Animação (WebM)</td><td>barra da vista, no transitório e no AC</td></tr><tr><td>Modelo como código</td><td>botão <code>&lt;/&gt;</code> ao lado de <strong>Modelo</strong>: script do console que recria o projeto</td></tr></tbody></table><p>O script exportado recria o modelo exatamente, com os mesmos ids. Ele é a base para <a href="./../scripting/console.html">automação</a>.</p>',17)])])}const h=o(s,[["render",i]]);export{u as __pageData,h as default};
